-- D1-BOTTLENECK-ISSUES-1 (2026-11-04, pillar cost; owner: D1 is the bottleneck, a query took 21 minutes). Files five implementation issues; RETENTION-SWEEP-1 and DATA-LAKE-1 already exist and are not duplicated.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM agent_issues WHERE source = 'session:cost-ledger-allvendor' AND title LIKE 'D1-%-1:%'
-- BACKUP: agent_issues

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'D1-TABLE-SPRAWL-1: audit and retire unused qnfo-audit tables, views and triggers (878 tables, 52 triggers on one insert)', 'Owner 2026-11-04: D1 is the bottleneck; a query waited 21 minutes. Measured 2026-11-04: qnfo-audit is one 1.5 GB database with 878 tables/views, a single writer, 680k queries and 2.39 B rows read a day; one fleet_tick insert fires dozens of triggers. Do: list every table/view/trigger with last read and last write (D1 analytics plus fleet-graph d1t: nodes), mark those with no reader in 30 days, archive to R2 (BACKUP rule) then drop in migrations, one family per migration with a rollback line; cap new tables per PR by a guard. Done when table+view count is below 400 and rows read per day is below 1 B. Closing probe: d1-query SELECT COUNT(*) FROM sqlite_master WHERE type IN (''table'',''view'') < 400.', 'session:cost-ledger-allvendor', 'optimization', 'high', 'open', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title = 'D1-TABLE-SPRAWL-1: audit and retire unused qnfo-audit tables, views and triggers (878 tables, 52 triggers on one insert)' AND status = 'open');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'D1-QUERY-BUDGET-1: every D1 statement gets a time and rows-read budget, slow queries are killed and filed, never waited on', 'Owner 2026-11-04: waiting 21 minutes for a D1 query is unacceptable. Add a shared wrapper (timeout 10 s, rows_read ceiling from meta) used by dashboard, fleet-control, cloud-ops and the MCP query tool; over-budget statements are aborted, logged to one table with the SQL fingerprint, and filed as a hotspot issue with their monthly USD from cost_vendor_month (d1/rows_read, $0.001 per million over 25 B). Done when no caller can block longer than 15 s on D1 and the top 20 fingerprints by rows read are listed daily. Closing probe: d1-query on the hotspot table having a row in the last 24 h and p99 statement time under 15 s.', 'session:cost-ledger-allvendor', 'optimization', 'high', 'open', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title = 'D1-QUERY-BUDGET-1: every D1 statement gets a time and rows-read budget, slow queries are killed and filed, never waited on' AND status = 'open');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'D1-SPLIT-HOT-TABLES-1: move fleet_tick, fleet_runs, cloud_ops_events, remediation_verifications, worker_logs into a second D1 database', 'Hot append-only operational tables share one writer with the audit tables, so one heavy statement blocks everything (overload errors 10-second windows). Split into a qnfo-ops-hot database with its own binding; keep views that join across them out of the tick path; migrate with dual-write then cutover, row-count verified. Done when overload errors (worker_logs ''overloaded'') are 0 for 24 h and qnfo-audit statements p95 under 1 s. Depends on D1-TABLE-SPRAWL-1 for what is moved.', 'session:cost-ledger-allvendor', 'optimization', 'high', 'open', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title = 'D1-SPLIT-HOT-TABLES-1: move fleet_tick, fleet_runs, cloud_ops_events, remediation_verifications, worker_logs into a second D1 database' AND status = 'open');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'D1-READ-PATHS-OFF-PRIMARY-1: serve dashboard and status reads from replicas, KV or cached snapshots', 'Read replication is enabled (auto) but nothing calls withSession; every read hits the primary. Move dashboard, /api/cost, v3 and MCP read-only queries to db.withSession(''first-unconstrained'') or an hourly materialized snapshot in KV/R2 for rarely changing views (v_output_quality_headline 1.5M rows per read). Done when the primary serves under 30% of read queries and rows read per day falls below 0.83 B (the 25 B/month allowance, which takes D1 reads from about USD 35 to USD 0). Measure with cost_usage_daily d1/rows_read.', 'session:cost-ledger-allvendor', 'optimization', 'high', 'open', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title = 'D1-READ-PATHS-OFF-PRIMARY-1: serve dashboard and status reads from replicas, KV or cached snapshots' AND status = 'open');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'D1-ROWS-READ-TOP20-1: fix the 20 statements that read the most rows, with a USD before and after each', 'Measured 2026-11-04 10:00-20:00Z (d1QueriesAdaptiveGroups): top readers include UPDATE persona_briefs (68 M rows in 45 calls, reads v_output_quality_headline), fleet_tick insert (42 M), fingerprint COUNT over fleet_issue_loop (40 M in 339 calls), INSERT OR REPLACE program_focus_plan_now from v_program_focus_plan (38 M in 80 calls), fg_edge OFFSET paging (23 M), reach_signals join (19 M). Each 1 B rows is USD 1 over the allowance; D1 is about USD 35 a month at the current 2 B/day, 0 at under 0.83 B/day. Add indexes or cache tables per statement, record before/after rows read and USD in decision_log. Done when the day total is under 0.83 B rows.', 'session:cost-ledger-allvendor', 'optimization', 'medium', 'open', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title = 'D1-ROWS-READ-TOP20-1: fix the 20 statements that read the most rows, with a USD before and after each' AND status = 'open');
